import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Thumbnail","description":"","frontmatter":{},"headers":[],"relativePath":"components/thumbnail.md","filePath":"components/thumbnail.md"}'),r={name:"components/thumbnail.md"};function d(n,t,h,l,c,s){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="thumbnail" tabindex="-1">Thumbnail <a class="header-anchor" href="#thumbnail" aria-label="Permalink to &quot;Thumbnail&quot;">​</a></h1><p>Thumbnail is a small picture of a document or a file, with an icon in its place when there is no picture.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it at the start of a list item, or at full width at the top of a card. When the image fails to load, <code>onerror</code> lets the application drop it so that the icon shows. A person is an <a href="./avatar">Avatar</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>src</code></td><td></td><td>The image; without it the icon shows</td></tr><tr><td><code>alt</code></td><td><code>&#39;&#39;</code></td><td>The text alternative (empty when decorative)</td></tr><tr><td><code>size</code></td><td><code>3rem</code></td><td>The width in rem, or <code>full</code></td></tr><tr><td><code>icon</code></td><td><code>image</code></td><td>The icon without an image: a name or a component</td></tr><tr><td><code>onerror</code></td><td></td><td>Called when the image fails to load</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The width is <code>size</code> and the height two thirds of it (3:2); with <code>full</code> it fills the container at 16:10. The surface is <code>--kata-color-raise-2</code> with one line in <code>--kata-color-line</code>, the image covers it and the icon is centred in the muted color. Thumbnail never shrinks in a row; in a list item it holds pad-md above and below, which makes the item as tall as <code>--kata-height-thumbnail-row</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/thumbnail/" title="Thumbnail" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/thumbnail/" target="_blank" rel="noopener">Thumbnail</a></figcaption></figure>',10)])])}const u=e(r,[["render",d]]);export{p as __pageData,u as default};
